import{_ as e,c as t,o as a,a2 as r}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Logic Repository Traits","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"Logic Traits"},"headers":[],"relativePath":"system-reference/backend/repository-traits/logic/overview.md","filePath":"system-reference/backend/repository-traits/logic/overview.md","lastUpdated":1777449208000}'),o={name:"system-reference/backend/repository-traits/logic/overview.md"},i=r('<h1 id="logic-repository-traits" tabindex="-1">Logic Repository Traits <a class="header-anchor" href="#logic-repository-traits" aria-label="Permalink to &quot;Logic Repository Traits&quot;">​</a></h1><p>These traits live in the <code>Repositories\\Logic</code> namespace and are composed directly into the base <code>Repository</code> class. They are <strong>not</strong> opt-in — every repository gets them automatically. Together they provide the full infrastructure layer: query building, relationship hydration, lifecycle hooks, date normalisation, event dispatch, collation, caching, and timestamp management.</p><h2 id="trait-reference" tabindex="-1">Trait Reference <a class="header-anchor" href="#trait-reference" aria-label="Permalink to &quot;Trait Reference&quot;">​</a></h2><table><thead><tr><th>Trait</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./QueryBuilder">QueryBuilder</a></td><td>Paginated listing, single-record lookup, multi-ID fetching, and flat-list helpers</td></tr><tr><td><a href="./MethodTransformers">MethodTransformers</a></td><td>Lifecycle hook dispatcher — fans out to every <code>{hookName}{Trait}</code> method across loaded traits</td></tr><tr><td><a href="./Relationships">Relationships</a></td><td>Syncs all Eloquent relationship types (BelongsToMany, HasMany, MorphMany, MorphTo, MorphToMany) on save</td></tr><tr><td><a href="./RelationshipHelpers">RelationshipHelpers</a></td><td>Reflection-based relationship discovery and foreign key resolution</td></tr><tr><td><a href="./Schema">Schema</a></td><td>Active schema management and input chunking helpers</td></tr><tr><td><a href="./CountBuilders">CountBuilders</a></td><td>Cached aggregate counts for status tabs (all, published, draft, trash)</td></tr><tr><td><a href="./Dates">Dates</a></td><td>Normalises date fields to <code>Y-m-d H:i:s</code> before save</td></tr><tr><td><a href="./DispatchEvents">DispatchEvents</a></td><td>Dispatches domain events (create/update/delete/restore) after database commit</td></tr><tr><td><a href="./CollationSelector">CollationSelector</a></td><td>Applies explicit MySQL collation to LIKE search queries on text columns</td></tr><tr><td><a href="./CacheableTrait">CacheableTrait</a></td><td>Relationship-aware caching for index and record queries</td></tr><tr><td><a href="./InspectTraits">InspectTraits</a></td><td>Runtime introspection — checks whether repository or model uses a given trait</td></tr><tr><td><a href="./TouchableEloquentModel">TouchableEloquentModel</a></td><td>Deferred <code>updated_at</code> touching — fires exactly once after all relationship syncs</td></tr></tbody></table>',4),s=[i];function d(n,c,l,h,p,f){return a(),t("div",null,s)}const y=e(o,[["render",d]]);export{m as __pageData,y as default};
